#!/usr/bin/env python3
import sys, json
L = [71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64]
nums = set(L)
# precompute possible triples
triples = []
for i,a in enumerate(L):
    for j,b in enumerate(L):
        if j<=i: continue
        s = a+b
        if s in nums and s!=a and s!=b:
            triples.append((a,b,s))
# sort to improve search
triples.sort(key=lambda t: (t[2], t[0]+t[1]))
used = set()
solution = []

sys.setrecursionlimit(10000)

def backtrack(start):
    if len(solution)==15:
        return True
    # pick next unused number as smallest to prune
    for idx in range(start, len(triples)):
        a,b,c = triples[idx]
        if a in used or b in used or c in used:
            continue
        # add
        used.update([a,b,c])
        solution.append((a,b,c))
        if backtrack(idx+1):
            return True
        # revert
        used.difference_update([a,b,c])
        solution.pop()
    return False

found = backtrack(0)
if not found:
    witness = {"polarity":"negative","basis":"search","search_exhausted":true,"nodes_explored":len(triples),"method":"backtrack"}
else:
    witness = {"polarity":"positive","data":{"triples":solution}}
print('WITNESS: '+json.dumps(witness))
